(function(e){e.JobLabContent=Object.assign(e.JobLabContent||{},{"KK-991":{scenario:{company:"Ngọc Hà Ocean Chartering",supervisor:{name:"Phan Thị Thu Trang",role:{vi:"Trưởng phòng Khai thác & Thuê tàu",en:"Head of Chartering & Operations"}},ref_code:"LT-5520",title:{vi:"Đúng điều khoản laytime. Đúng tiền phạt chậm. SOF trung thực.",en:"Right laytime terms. Right demurrage. A truthful SOF."},brief:{vi:"Tàu xếp 33.000 tấn than tại cảng xếp với mức xếp 6.000 tấn/ngày. Laytime bắt đầu tính từ 08:00 thứ Năm, xếp xong lúc 23:00 thứ Năm tuần sau; không có ngày lễ, không ngừng do thời tiết. Mức phạt bốc dỡ chậm 16.800 USD/ngày, tính theo tỷ lệ thời gian. Bản nháp bảng tính LT-5520 áp điều khoản SHINC và tính phạt 35700 USD. Đối chiếu hợp đồng thuê tàu đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"A vessel loads 33,000 t of coal at a loading rate of 6,000 t per day. Laytime starts at 08:00 on Thursday and loading completes at 23:00 the following Thursday; there are no holidays and no weather stoppages. Demurrage is 16,800 USD per day, pro rata. Draft laytime statement LT-5520 applies SHINC terms and claims 35700 USD. Compare it with the approved charter party, correct both fields and write an evidence-based report."},reference_title:{vi:"Hợp đồng thuê chuyến & SOF đã ký · LT-5520",en:"Approved charter party & signed SOF · LT-5520"},fields:[{id:"LAY_TERMS",label:{vi:"Điều khoản tính laytime",en:"Laytime counting terms"},initial:"SHINC",expected:"SHEX",choices:["SHINC","SHEX","SSHEX"],reference:"Hợp đồng thuê chuyến - điều khoản laytime",hint:{vi:"Hợp đồng đã duyệt loại trừ Chủ nhật và ngày lễ khỏi laytime, còn thứ Bảy vẫn được tính.",en:"The approved charter party excludes Sundays and holidays from laytime, while Saturdays still count."}},{id:"DEMURRAGE",label:{vi:"Tiền phạt bốc dỡ chậm (USD)",en:"Demurrage due (USD)"},initial:"35700",expected:"18900",reference:"Bảng tính laytime",ref_value:{vi:"33.000 tấn ÷ 6.000 tấn/ngày; từ 08:00 thứ Năm đến 23:00 thứ Năm tuần sau; 16.800 USD/ngày",en:"33,000 t ÷ 6,000 t per day; from 08:00 Thursday to 23:00 the following Thursday; 16,800 USD per day"},hint:{vi:"Tính số giờ được phép, rồi trừ trọn ngày Chủ nhật khỏi thời gian đã dùng vì Chủ nhật rơi vào trong laytime.",en:"Work out the allowed hours, then deduct the whole Sunday from time used because it falls within laytime."}}],sop32:{vi:"Laytime cho phép = khối lượng ÷ mức xếp (ngày x 24 giờ); thời gian tính = thời gian thực tế trừ các khoảng loại trừ theo điều khoản; phạt = (giờ tính - giờ cho phép) ÷ 24 x mức phạt/ngày.",en:"Allowed laytime = quantity ÷ loading rate (days x 24 hours); time counted = elapsed time minus exceptions under the clause; demurrage = (hours counted - hours allowed) ÷ 24 x daily rate."},context:{label:"SOF / LT-5520",metrics:[{label:{vi:"Khối lượng hàng",en:"Cargo quantity"},value:"33,000 t"},{label:{vi:"Mức xếp",en:"Loading rate"},value:"6,000 t/day"},{label:{vi:"Mức phạt chậm",en:"Demurrage rate"},value:"16,800 USD/day"}]},crisis:{vi:"Người thuê tàu nhắn: “Anh sửa giúp SOF, ghi thêm 6 tiếng mưa ngừng xếp vào thứ Ba để giảm tiền phạt. Bên tôi sẽ ưu tiên ký thêm 3 chuyến và có phần cảm ơn riêng cho anh.”",en:"The charterer texts: “Please edit the SOF and add 6 hours of rain stoppage on Tuesday to cut the demurrage. We'll prioritise 3 more fixtures with you and there's a personal thank-you for you.”"},options:{safe:{vi:"Từ chối sửa SOF, dùng SOF đã được thuyền trưởng và đại lý ký, báo trưởng phòng về đề nghị; nếu cần thì thương lượng giảm phạt minh bạch bằng văn bản giữa hai công ty.",en:"Refuse to edit the SOF, use the SOF signed by the master and agent, report the offer to the head of department and, if needed, negotiate any reduction transparently in writing."},shortcut:{vi:"Thêm 6 giờ mưa vào SOF để giữ khách và nhận phần cảm ơn.",en:"Add 6 rain hours to the SOF to keep the client and take the thank-you."},wait:{vi:"Để yêu cầu đó lại, chờ người thuê tàu tự gửi bảng tính khác.",en:"Leave the request and wait for the charterer to send another calculation."}},questions:{vi:["Vì sao phải áp SHEX thay vì SHINC? Điều khoản nào chứng minh và nó làm thời gian tính thay đổi ra sao?","Trình bày cách tính tiền phạt bốc dỡ chậm và rủi ro pháp lý nếu chỉnh sửa SOF theo đề nghị của người thuê tàu."],en:["Why apply SHEX instead of SHINC? Which clause proves it and how does it change time counted?","Explain how you calculated demurrage and the legal risk of editing the SOF at the charterer's request."]},hints:{vi:["Đọc điều khoản laytime trong hợp đồng đã duyệt và đánh dấu những ngày được loại trừ.","Tính giờ cho phép và giờ đã dùng sau loại trừ theo SOP mục 3.2, rồi mới nhân mức phạt.","Đọc lại SOP mục 4.2: SOF là chứng từ gốc, không được sửa theo yêu cầu thương mại."],en:["Read the laytime clause in the approved charter party and mark the excepted days.","Compute allowed hours and hours used after exceptions per SOP 3.2 before applying the rate.","Re-read SOP 4.2: the SOF is a source document and must never be edited for commercial reasons."]}},learning:{summary:{vi:"Chuyên viên khai thác tàu và thuê tàu tìm hàng, chào tàu, đàm phán và chốt hợp đồng thuê chuyến, thuê định hạn, lập dự toán chuyến đi, chỉ định đại lý, theo dõi tàu tại cảng và tính laytime, demurrage, despatch. Nghề đòi hỏi am hiểu thị trường vận tải biển, điều khoản hợp đồng thuê tàu, vận đơn, luật hàng hải và giữ chứng từ trung thực để bảo vệ công ty khi phát sinh tranh chấp.",en:"A ship operations and chartering officer finds cargoes, offers tonnage, negotiates and fixes voyage and time charters, prepares voyage estimates, appoints agents, follows vessels in port and calculates laytime, demurrage and despatch. The role requires knowledge of shipping markets, charter party clauses, bills of lading and maritime law, and truthful documents that protect the company in disputes."},responsibilities:{vi:["Theo dõi thị trường, chào tàu, đàm phán điều khoản và chốt hợp đồng thuê tàu.","Lập dự toán chuyến đi: nhiên liệu, phí cảng, thời gian và lợi nhuận ngày tàu.","Chỉ định đại lý, gửi chỉ thị chuyến đi, theo dõi NOR, SOF và tiến độ làm hàng.","Tính laytime, demurrage, despatch và quyết toán cước với người thuê tàu.","Xử lý khiếu nại hàng hóa, tranh chấp hợp đồng và phối hợp với bảo hiểm P&I."],en:["Watch the market, offer tonnage, negotiate terms and fix charters.","Prepare voyage estimates: bunkers, port costs, time and daily earnings.","Appoint agents, issue voyage instructions and track NOR, SOF and cargo progress.","Calculate laytime, demurrage and despatch and settle freight with charterers.","Handle cargo claims and contract disputes and liaise with P&I insurers."]},competencies:[{name:{vi:"Đàm phán thuê tàu",en:"Charter negotiation"},desc:{vi:"Đàm phán cước, laytime, điều khoản loại trừ và trách nhiệm để cân bằng lợi ích và rủi ro.",en:"Negotiate freight, laytime, exceptions and liabilities to balance earnings and risk."}},{name:{vi:"Dự toán chuyến đi",en:"Voyage estimating"},desc:{vi:"Tính chi phí, thời gian, TCE và so sánh các phương án chuyến đi.",en:"Calculate costs, time and TCE and compare voyage options."}},{name:{vi:"Tính laytime & demurrage",en:"Laytime & demurrage"},desc:{vi:"Áp đúng điều khoản SHINC, SHEX, thời điểm bắt đầu và các khoảng loại trừ trong SOF.",en:"Apply SHINC or SHEX, the commencement time and SOF exceptions correctly."}},{name:{vi:"Quản lý chứng từ hàng hải",en:"Shipping documentation"},desc:{vi:"Kiểm soát NOR, SOF, vận đơn, biên bản hàng hóa đầy đủ, nhất quán và đúng thời hạn.",en:"Keep NOR, SOF, bills of lading and cargo reports complete, consistent and on time."}},{name:{vi:"Đạo đức thương mại",en:"Commercial ethics"},desc:{vi:"Không làm sai lệch chứng từ, không nhận lợi ích cá nhân, minh bạch khi thương lượng.",en:"Never falsify documents or take personal benefits and negotiate transparently."}}],knowledge:{vi:["Bộ luật Hàng hải Việt Nam 2015 về hợp đồng vận chuyển theo chuyến, thuê tàu định hạn và vận đơn.","Mẫu hợp đồng thuê chuyến tiêu chuẩn như GENCON và thuê định hạn như NYPE.","Định nghĩa laytime cho hợp đồng thuê tàu 2013: SHINC, SHEX, WWD, NOR và các thuật ngữ liên quan.","Quy tắc Hague-Visby về trách nhiệm của người vận chuyển theo vận đơn.","Nguyên tắc once on demurrage, always on demurrage và cách áp dụng khoảng loại trừ."],en:["Vietnam Maritime Code 2015 on voyage charters, time charters and bills of lading.","Standard voyage charter forms such as GENCON and time charter forms such as NYPE.","Laytime Definitions for Charter Parties 2013: SHINC, SHEX, WWD, NOR and related terms.","The Hague-Visby Rules on carrier liability under bills of lading.","The once on demurrage, always on demurrage principle and how exceptions apply."]},tools:["Phần mềm dự toán chuyến đi","Hệ thống theo dõi tàu AIS","Bảng tính laytime","Cơ sở dữ liệu khoảng cách cảng","Bản tin thị trường cước"],kpis:{vi:["Lợi nhuận ngày tàu (TCE) thực tế so với dự toán.","Tỷ lệ quyết toán demurrage trong 60 ngày sau khi kết thúc chuyến.","Số tranh chấp do sai sót chứng từ hoặc tính toán (mục tiêu bằng 0).","Thời gian tàu chờ cầu bình quân mỗi chuyến."],en:["Actual time charter equivalent (TCE) versus the estimate.","Share of demurrage claims settled within 60 days of voyage end.","Disputes caused by document or calculation errors (target zero).","Average berth waiting time per voyage."]},day:[{time:"08:00",vi:"Xem vị trí đội tàu, báo cáo trưa và tin thị trường cước.",en:"Check fleet positions, noon reports and freight market news."},{time:"09:30",vi:"Lập dự toán chuyến đi cho đơn chào hàng mới và đàm phán với môi giới.",en:"Prepare a voyage estimate for a new cargo offer and negotiate with brokers."},{time:"11:00",vi:"Gửi chỉ thị chuyến đi, kiểm tra NOR và kế hoạch làm hàng với đại lý.",en:"Send voyage instructions and check NOR and the cargo plan with the agent."},{time:"14:00",vi:"Tính laytime, demurrage theo SOF đã ký và gửi bảng tính cho người thuê.",en:"Calculate laytime and demurrage from the signed SOF and send it to the charterer."},{time:"16:30",vi:"Cập nhật lịch tàu, rủi ro thời tiết và báo cáo trưởng phòng.",en:"Update the vessel schedule and weather risks and report to the department head."}],mistakes:{vi:["Áp sai điều khoản loại trừ SHINC, SHEX khi tính laytime.","Bỏ qua nguyên tắc once on demurrage, always on demurrage hoặc xác định sai thời điểm bắt đầu laytime.","Chỉnh sửa SOF hoặc nhận lợi ích cá nhân để giảm phạt cho khách hàng."],en:["Applying the wrong SHINC or SHEX exceptions when counting laytime.","Ignoring once on demurrage, always on demurrage or setting the wrong laytime start.","Editing the SOF or accepting personal benefits to reduce a client's demurrage."]},career:[{vi:"Nhân viên khai thác tàu",en:"Operations assistant"},{vi:"Chuyên viên khai thác & thuê tàu",en:"Ship operations & chartering officer"},{vi:"Trưởng nhóm thuê tàu",en:"Chartering manager"},{vi:"Giám đốc thương mại hàng hải",en:"Commercial director, shipping"}],glossary:[{term:"Laytime",vi:"Thời gian làm hàng cho phép theo hợp đồng mà chủ tàu không thu thêm tiền.",en:"Time allowed in the charter for cargo work without extra payment to the owner."},{term:"Demurrage",vi:"Tiền phạt người thuê trả cho chủ tàu khi làm hàng vượt quá laytime.",en:"Money the charterer pays the owner when cargo work exceeds laytime."},{term:"NOR",vi:"Thông báo sẵn sàng làm hàng thuyền trưởng gửi khi tàu đã đến và sẵn sàng về mọi mặt.",en:"Notice of readiness from the master once the vessel has arrived and is ready in all respects."},{term:"SOF",vi:"Biên bản sự kiện ghi thời điểm đến, làm hàng, ngừng và hoàn thành, có chữ ký các bên.",en:"Statement of facts recording arrival, cargo work, stoppages and completion, signed by the parties."},{term:"SHEX",vi:"Chủ nhật và ngày lễ không tính vào laytime.",en:"Sundays and holidays excepted from laytime."}],quiz:[{q:{vi:"Hàng 24.000 tấn, mức xếp 8.000 tấn/ngày theo SHINC. Laytime cho phép là bao nhiêu giờ?",en:"Cargo of 24,000 t at 8,000 t per day SHINC. How many hours of laytime are allowed?"},options:{vi:["48 giờ","96 giờ","72 giờ","24 giờ"],en:["48 hours","96 hours","72 hours","24 hours"]},answer:2,explain:{vi:"24.000 ÷ 8.000 = 3 ngày = 72 giờ.",en:"24,000 ÷ 8,000 = 3 days = 72 hours."}},{q:{vi:"SHEX có nghĩa là gì?",en:"What does SHEX mean?"},options:{vi:["Chủ nhật và ngày lễ được loại trừ","Chủ nhật và ngày lễ vẫn tính","Thứ Bảy, Chủ nhật và ngày lễ được loại trừ","Chỉ tính ngày thời tiết tốt"],en:["Sundays and holidays excepted","Sundays and holidays included","Saturdays, Sundays and holidays excepted","Only good weather days count"]},answer:0,explain:{vi:"SHEX loại trừ Chủ nhật và ngày lễ; SHINC tính cả hai; SSHEX loại trừ thêm thứ Bảy.",en:"SHEX excludes Sundays and holidays; SHINC includes them; SSHEX also excludes Saturdays."}},{q:{vi:"Người thuê tàu nhờ sửa SOF để giảm phạt và hứa thêm hợp đồng. Bạn làm gì?",en:"A charterer asks you to edit the SOF to cut demurrage and promises more business. What do you do?"},options:{vi:["Sửa vì khách quan trọng","Sửa một nửa số giờ","Chờ khách gửi lại yêu cầu","Từ chối, dùng SOF đã ký và báo cáo trưởng phòng"],en:["Edit it because the client matters","Edit half the hours","Wait for the client to ask again","Refuse, use the signed SOF and report to the department head"]},answer:3,explain:{vi:"SOF là chứng từ gốc; làm sai lệch là gian lận và gây rủi ro pháp lý nghiêm trọng cho công ty.",en:"The SOF is a source document; falsifying it is fraud and creates serious legal risk."}},{q:{vi:"Theo nguyên tắc once on demurrage, always on demurrage, Chủ nhật rơi vào sau khi laytime đã hết thì sao?",en:"Under once on demurrage, always on demurrage, what happens to a Sunday after laytime has expired?"},options:{vi:["Được loại trừ như thường","Vẫn tính vào thời gian phạt chậm, trừ khi hợp đồng quy định khác","Tính gấp đôi","Hủy toàn bộ tiền phạt"],en:["Excepted as usual","Counts as demurrage time unless the charter says otherwise","Counts double","Cancels all demurrage"]},answer:1,explain:{vi:"Khi tàu đã vào thời gian phạt, các khoảng loại trừ của laytime thường không còn áp dụng.",en:"Once the vessel is on demurrage, laytime exceptions normally no longer apply."}}],tools_en:["Voyage estimation software","AIS vessel tracking system","Laytime calculation spreadsheet","Port distance database","Freight market reports"]}}})})(window.KKR);
